function Mark({ small = false }) { return <a className={`brand ${small ? 'brand-small' : ''}`} href="/" aria-label="شکیب لرن، صفحه نخست"><img src="/shakiblearn-logo.png" alt="" /><span><strong>شکیب لرن</strong><small>آموزش تخصصی داروسازی و فرمولاسیون</small></span></a>; }
function Arrow() { return null; }
let csrfToken = null;
async function api(path, options = {}) { const response=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});let data={};try{data=await response.json();}catch{}if(!response.ok)throw new Error(data.error||'ارتباط با سرویس انجام نشد.');return data; }
async function apiWrite(path, method, body) { if(!csrfToken){const session=await api('/api/auth/session');csrfToken=session.csrf;} if(!csrfToken)throw new Error('برای انجام این کار وارد حساب شوید.');return api(path,{method,headers:{'X-CSRF-Token':csrfToken},body:JSON.stringify(body)}); }
function cartRead(){try{return JSON.parse(localStorage.getItem('daro-cart')||'[]')}catch{return []}}
function cartWrite(items){localStorage.setItem('daro-cart',JSON.stringify(items));window.dispatchEvent(new Event('daro-cart-change'));}

function Header({ path, theme, onTheme }) {
  const [open, setOpen] = useState(false);
  const [cartCount, setCartCount] = useState(()=>cartRead().reduce((n,x)=>n+(Number(x.quantity)||0),0));
  React.useEffect(()=>{const sync=()=>setCartCount(cartRead().reduce((n,x)=>n+(Number(x.quantity)||0),0));window.addEventListener('daro-cart-change',sync);window.addEventListener('storage',sync);return()=>{window.removeEventListener('daro-cart-change',sync);window.removeEventListener('storage',sync)}},[]);
  return <>
    <header className="header"><div className="wrap nav-row"><Mark /><button className="menu-toggle" aria-label={open ? 'بستن فهرست' : 'باز کردن فهرست'} aria-expanded={open} onClick={() => setOpen(!open)}>{open ? 'بستن' : 'منو'}</button><nav className={open ? 'nav open' : 'nav'}>{sections.slice(0, 6).map(s => <a className={path === s.href ? 'active' : ''} key={s.id} href={s.href} onClick={() => setOpen(false)}>{s.title}</a>)}<a className="mobile-download-link" href="/download" onClick={() => setOpen(false)}>دانلود اپلیکیشن</a><details className="services-menu"><summary>همهٔ خدمات</summary><div>{sections.slice(6).map(s => <a key={s.id} href={s.href}>{s.title}<Arrow /></a>)}<a href="/shortages">گزارش کمبود دارو<Arrow /></a><a href="/shifts">تبادل شیفت<Arrow /></a><a href="/universities">دانشگاه‌ها<Arrow /></a></div></details></nav><div className="nav-tools"><button className="theme-toggle" onClick={onTheme} aria-label={theme === 'dark' ? 'فعال کردن حالت روشن' : 'فعال کردن حالت تاریک'} title={theme === 'dark' ? 'حالت روشن' : 'حالت تاریک'}>{theme === 'dark' ? 'حالت روشن' : 'حالت تیره'}</button><a className="cart-link" href="/cart" aria-label={`سبد خرید، ${cartCount} قلم`}><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M3 4h2l2.3 11.2a2 2 0 0 0 2 1.6h8.9a2 2 0 0 0 1.9-1.5L22 8H6"/><circle cx="10" cy="20" r="1.2"/><circle cx="18" cy="20" r="1.2"/></svg><span>{cartCount.toLocaleString('fa-IR')}</span><b>سبد</b></a><a className="download-cta" href="/download">دانلود اپلیکیشن</a><a className="login" href="/login">ورود</a></div></div></header>
  </>;
}

function SearchBox({ route = '/drugs', placeholder = 'نام دارو، مادهٔ مؤثره یا موضوع را بنویسید' }) {
  const [term, setTerm] = useState('');
  const [message, setMessage] = useState('');
  return <form className="searchbox" action="/search" method="get"><input name="q" aria-label="جست‌وجو" placeholder={placeholder} value={term} onChange={e => { setTerm(e.target.value); setMessage(''); }} /><button type="submit">جست‌وجو</button>{message && <span className="search-note" role="status">{message}</span>}</form>;
}

function ChemistryArt() {
  return <div className="art-stage"><img src="/media/shakib-workshop.jpg" alt="آماده‌سازی فرآوردهٔ ترکیبی در کارگاه داروسازی شکیب لرن" fetchPriority="high" /></div>;
}

